use openbridge::{lowering::generation::{check,GenerationRepresentationContract},protocol::openai::{chat,responses},semantic::task::generation::{GenerationRequirements,Item}};
#[test] fn chat_ir_responses_vertical_slice(){let source=serde_json::json!({"messages":[{"role":"system","content":"Be precise."},{"role":"user","content":"Hello"}],"temperature":0.25,"max_completion_tokens":128});let d=chat::decode_generation(&source).unwrap();let q=GenerationRequirements::derive(&d.semantic);assert_eq!(q.instruction_count,1);assert_eq!(q.message_count,1);check(&d.semantic,GenerationRepresentationContract::full_text()).unwrap();let target=responses::encode_generation(&d.semantic);assert_eq!(target["input"][1]["content"][0]["text"],"Hello");assert_eq!(target["max_output_tokens"],128);}
#[test] fn ir_deletion_controls_both_encoders(){let source=serde_json::json!({"messages":[{"role":"system","content":"obsolete"},{"role":"user","content":"keep"}]});let d=chat::decode_generation(&source).unwrap();let ir=d.semantic.retain_items(|_,item|!matches!(item,Item::Instruction(_))).unwrap();let chat_out=chat::encode_generation(&ir);let responses_out=responses::encode_generation(&ir);assert_eq!(chat_out["messages"].as_array().unwrap().len(),1);assert_eq!(responses_out["input"].as_array().unwrap().len(),1);assert_eq!(chat_out["messages"][0]["content"],"keep");assert_eq!(responses_out["input"][0]["content"][0]["text"],"keep");}
#[test] fn unrepresentable_semantics_fail_before_encoding(){let source=serde_json::json!({"messages":[{"role":"system","content":"required"},{"role":"user","content":"hello"}]});let d=chat::decode_generation(&source).unwrap();let c=GenerationRepresentationContract{instructions:false,temperature:true,max_output_tokens:true};assert!(check(&d.semantic,c).is_err());}
